def transform(grid):
    """Repeat the non-background pattern from the first compartment in all matching compartments."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Uniform full-length lines in a non-background color divide the grid into panels.
    div_rows = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != bg]
    div_cols = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != bg]
    row_edges = [-1] + div_rows + [h]
    col_edges = [-1] + div_cols + [w]
    row_spans = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)
                 if row_edges[i + 1] > row_edges[i] + 1]
    col_spans = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)
                 if col_edges[i + 1] > col_edges[i] + 1]

    panels = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            panel = [row[c0:c1] for row in g[r0:r1]]
            if any(value != bg for row in panel for value in row):
                panels.append((r0, r1, c0, c1, panel))
    if len(panels) != 1:
        return g

    source = panels[0][4]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if (r1 - r0, c1 - c0) == (len(source), len(source[0])):
                for dr in range(len(source)):
                    for dc in range(len(source[0])):
                        g[r0 + dr][c0 + dc] = source[dr][dc]
    return g
